(()=>{
'use strict';
if(window.__gtavModsLibraryV11)return;
window.__gtavModsLibraryV11=true;

const API='/api/mods';
const FALLBACK=[
 {id:'community-pack-1',title:'Community Mod Pack 1',category:'modpack',subtitle:'Gameplay & realism',description:'Gore improvements, DriveV, realistic pedestrians and traffic, plus new forests and abandoned cabins.',downloadUrl:'https://gofile.io/d/RNlatXEi',imageUrl:'assets/los-santos-background.jpeg',preview2Url:'',presetUrl:'',tags:['4 improvements','Gameplay'],languageCode:'',sortOrder:10,published:true},
 {id:'dlc-pack-1',title:'DLC Pack 1',category:'dlc',subtitle:'Dec 2014 — Oct 2016',description:'15 updates · 133 vehicles · 21 weapons',downloadUrl:'https://gofile.io/d/RdZWkpX8',tags:['15 updates','133 vehicles','21 weapons'],sortOrder:20,published:true},
 {id:'dlc-pack-2',title:'DLC Pack 2',category:'dlc',subtitle:'Dec 2016 — Sep 2018',description:'8 updates · 126 vehicles · 14 weapons',downloadUrl:'https://gofile.io/d/mkM4gKvY',tags:['8 updates','126 vehicles','14 weapons'],sortOrder:21,published:true},
 {id:'dlc-pack-3',title:'DLC Pack 3',category:'dlc',subtitle:'Dec 2018 — Aug 2020',description:'4 updates · 103 vehicles · 6 weapons',downloadUrl:'https://gofile.io/d/x7ltGZrC',tags:['4 updates','103 vehicles','6 weapons'],sortOrder:22,published:true},
 {id:'dlc-pack-4',title:'DLC Pack 4',category:'dlc',subtitle:'Dec 2020 — Jul 2022',description:'4 updates · 74 vehicles · 8 weapons',downloadUrl:'https://gofile.io/d/6LJ3NLlG',tags:['4 updates','74 vehicles','8 weapons'],sortOrder:23,published:true},
 {id:'awesomekills-graphics-ios',title:'Awesomekills Graphics iOS',category:'graphics',subtitle:'Lighting & timecycle',description:'Improves nighttime lighting and the timecycle for GTA V on iOS.',downloadUrl:'https://gofile.io/d/e726b04a-a872-4ab3-a5b5-d877e05fa422',imageUrl:'https://user13692.na.imgto.link/public/20261028/e2fc4facdafeabc469b5c8e2-img-8405.avif',preview2Url:'https://user13692.na.imgto.link/public/20261028/ae37373de6e09c391ff08a60-img-8408.avif',presetUrl:'assets/mods/awesomekills/GTA-V-graphics-settings-iPhone11.json',tags:['Night lighting','Timecycle'],sortOrder:30,published:true},
 {id:'language-ro',title:'Romanian',category:'language',subtitle:'Romanian',description:'Romanian translation pack for GTA V.',downloadUrl:'https://gofile.io/d/UBFyquIl',tags:['Translation'],languageCode:'RO',sortOrder:40,published:true},
 {id:'language-vi',title:'Vietnamese',category:'language',subtitle:'Vietnamese',description:'Vietnamese translation pack for GTA V.',downloadUrl:'https://gofile.io/d/inDXtUnp',tags:['Translation'],languageCode:'VI',sortOrder:41,published:true},
 {id:'language-th',title:'Thai',category:'language',subtitle:'Thai',description:'Thai translation pack for GTA V.',downloadUrl:'https://gofile.io/d/hSyKxoiG',tags:['Translation'],languageCode:'TH',sortOrder:42,published:true},
 {id:'language-ar',title:'Arabic',category:'language',subtitle:'Arabic',description:'Arabic translation pack for GTA V.',downloadUrl:'https://gofile.io/d/0KdSmVMg',tags:['Translation'],languageCode:'AR',sortOrder:43,published:true},
 {id:'language-id',title:'Indonesian',category:'language',subtitle:'Indonesian',description:'Indonesian translation pack for GTA V.',downloadUrl:'https://gofile.io/d/9u6eONPa',tags:['Translation'],languageCode:'ID',sortOrder:44,published:true}
];
const icon=name=>`<svg class="lib-icon" aria-hidden="true"><use href="assets/icons.svg#${name}"></use></svg>`;
const gridIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="6" height="6" rx="1.3"/><rect x="14" y="4" width="6" height="6" rx="1.3"/><rect x="4" y="14" width="6" height="6" rx="1.3"/><rect x="14" y="14" width="6" height="6" rx="1.3"/></svg>';
const listIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6h11M9 12h11M9 18h11"/><path d="M4 6h1M4 12h1M4 18h1"/></svg>';
const safe=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const categoryMeta={modpack:{label:'Mod Pack',icon:'package'},dlc:{label:'DLC',icon:'archive'},graphics:{label:'Graphics',icon:'palette'},language:{label:'Language',icon:'languages'}};

function normalize(item){return{id:String(item.id||crypto.randomUUID?.()||Math.random()),title:String(item.title||'Untitled mod'),category:['modpack','dlc','graphics','language'].includes(item.category)?item.category:'modpack',subtitle:String(item.subtitle||''),description:String(item.description||''),downloadUrl:String(item.downloadUrl||''),imageUrl:String(item.imageUrl||''),preview2Url:String(item.preview2Url||''),presetUrl:String(item.presetUrl||''),tags:Array.isArray(item.tags)?item.tags.map(String):[],languageCode:String(item.languageCode||''),sortOrder:Number(item.sortOrder||100),published:item.published!==false}}
function buildEntries(mods){
 const live=mods.filter(x=>x.published!==false).map(normalize).sort((a,b)=>a.sortOrder-b.sortOrder);
 const dlc=live.filter(x=>x.category==='dlc');
 const languages=live.filter(x=>x.category==='language');
 const entries=[];
 live.filter(x=>x.category==='modpack').forEach(x=>entries.push({...x,type:'modpack',count:1,icon:'package',visual:'modpack'}));
 if(dlc.length)entries.push({id:'dlc-collection',type:'dlc',category:'dlc',title:'DLC Collection',subtitle:`${dlc.length} release-era pack${dlc.length===1?'':'s'}`,description:'GTA Online content organized into downloadable DLC packs.',count:dlc.length,icon:'archive',visual:'dlc',children:dlc,tags:[`${dlc.length} packs`,...new Set(dlc.flatMap(x=>x.tags).filter(Boolean))].slice(0,3),sortOrder:Math.min(...dlc.map(x=>x.sortOrder))});
 live.filter(x=>x.category==='graphics').forEach(x=>entries.push({...x,type:'graphics',count:1,icon:'palette',visual:'graphics'}));
 if(languages.length)entries.push({id:'language-collection',type:'language',category:'language',title:'Language Packs',subtitle:`${languages.length} translation${languages.length===1?'':'s'}`,description:'Choose one translation pack for your preferred language.',count:languages.length,icon:'languages',visual:'language',children:languages,tags:[`${languages.length} packs`,'Translation'],sortOrder:Math.min(...languages.map(x=>x.sortOrder))});
 return{mods:live,entries:entries.sort((a,b)=>(a.sortOrder||100)-(b.sortOrder||100))};
}
function childRows(entry){
 if(entry.type==='dlc')return entry.children.map((x,i)=>`<a class="collection-row" href="${safe(x.downloadUrl)}" target="_blank" rel="noopener noreferrer"><span class="collection-index">${String(i+1).padStart(2,'0')}</span><span class="collection-copy"><strong>${safe(x.title)}</strong><small>${safe(x.subtitle||'DLC Pack')}</small><em>${safe(x.description)}</em></span><span class="collection-action">${icon('download-modern')}</span></a>`).join('');
 return entry.children.map(x=>`<a class="collection-row language-row" href="${safe(x.downloadUrl)}" target="_blank" rel="noopener noreferrer"><span class="language-code">${safe(x.languageCode||x.title.slice(0,2).toUpperCase())}</span><span class="collection-copy"><strong>${safe(x.title)}</strong><small>${safe(x.subtitle||'Language Pack')}</small></span><span class="collection-action">${icon('download-modern')}</span></a>`).join('');
}
function media(item){
 const meta=categoryMeta[item.category]||categoryMeta.modpack;
 if(item.imageUrl)return `<div class="library-media image-media"><img src="${safe(item.imageUrl)}" alt="${safe(item.title)} preview" loading="lazy" decoding="async"><span class="media-label">${icon(meta.icon)} ${meta.label}</span></div>`;
 if(item.visual==='modpack')return `<div class="library-media community-media"><img src="assets/los-santos-background.jpeg" alt="" loading="lazy" decoding="async"><span class="media-overlay"></span><span class="media-icon">${icon('package')}</span><small>MOD PACK</small></div>`;
 if(item.visual==='dlc')return `<div class="library-media abstract-media"><span class="media-icon">${icon('archive')}</span><strong>${String(item.count).padStart(2,'0')}</strong><small>DLC PACKS</small></div>`;
 if(item.visual==='language')return `<div class="library-media abstract-media language-media"><span class="media-icon">${icon('languages')}</span><strong>${String(item.count).padStart(2,'0')}</strong><small>LANGUAGE PACKS</small></div>`;
 return `<div class="library-media abstract-media"><span class="media-icon">${icon(meta.icon)}</span><small>${meta.label.toUpperCase()}</small></div>`;
}
function card(item){
 const meta=categoryMeta[item.category]||categoryMeta.modpack;
 const childSearch=(item.children||[]).map(x=>[x.title,x.subtitle,x.description,x.languageCode,...x.tags].join(' ')).join(' ');
 const search=[meta.label,item.title,item.subtitle,item.description,...(item.tags||[]),childSearch].join(' ').toLowerCase();
 const hasChildren=!!item.children;
 return `<article class="library-card${hasChildren?' has-children':''}" data-id="${safe(item.id)}" data-type="${safe(item.type)}" data-count="${item.count||1}" data-search="${safe(search)}">${media(item)}<div class="library-card-body"><div class="library-card-meta"><span>${icon(meta.icon)}${meta.label}</span><span>${item.count||1} download${(item.count||1)===1?'':'s'}</span></div><h3>${safe(item.title)}</h3><p class="library-card-subtitle">${safe(item.subtitle)}</p><p class="library-card-description">${safe(item.description)}</p><div class="library-tags">${(item.tags||[]).slice(0,3).map(t=>`<span>${safe(t)}</span>`).join('')}</div><div class="library-actions">${hasChildren?`<button class="collection-toggle" type="button" aria-expanded="false"><span>View ${item.count} ${item.type==='dlc'?'packs':'languages'}</span>${icon('chevron-down')}</button>`:`<a class="primary-action" href="${safe(item.downloadUrl)}" target="_blank" rel="noopener noreferrer">${icon('download-modern')}<span>Download</span></a>${item.presetUrl?`<a class="secondary-action" href="${safe(item.presetUrl)}"${item.presetUrl.startsWith('assets/')||item.presetUrl.startsWith('/assets/')?' download':''}>${icon('sliders')}<span>Preset</span></a>`:''}`}</div></div>${hasChildren?`<div class="collection-panel" hidden>${childRows(item)}</div>`:''}</article>`;
}

async function getMods(){try{const r=await fetch(API,{cache:'no-store'});if(!r.ok)throw new Error();const data=await r.json();if(Array.isArray(data.mods)&&data.mods.length)return data.mods}catch{}return FALLBACK}
async function mount(){
 const main=document.querySelector('.mods-studio');if(!main||main.dataset.libraryV11==='1')return;main.dataset.libraryV11='1';
 const source=await getMods();const built=buildEntries(source);const ITEMS=built.entries,total=built.mods.length;const counts={modpack:built.mods.filter(x=>x.category==='modpack').length,dlc:built.mods.filter(x=>x.category==='dlc').length,graphics:built.mods.filter(x=>x.category==='graphics').length,language:built.mods.filter(x=>x.category==='language').length};const categories=Object.values(counts).filter(Boolean).length;
 main.className='mods-studio mods-library-v10';
 main.innerHTML=`<section class="library-hero" aria-labelledby="library-title"><div class="library-hero-bg" aria-hidden="true"></div><div class="library-breadcrumb"><a href="home.html">Home</a><span>/</span><span>Mods</span></div><div class="library-hero-main"><img class="library-logo" src="https://user13692.na.imgto.link/public/20261028/a7a06b1488b4b44342b0cf18-img-8148.avif" alt="GTA V iOS Mods logo"><div class="library-hero-copy"><span>COMMUNITY LIBRARY</span><h1 id="library-title">GTA V iOS Mods</h1><p>Mods, DLC, graphics and translations for the native iOS project.</p></div></div><div class="library-stats"><span><strong>${total}</strong><small>Downloads</small></span><span><strong>${categories}</strong><small>Categories</small></span><span><strong>iOS</strong><small>Platform</small></span></div></section><section class="library-toolbar" aria-label="Mod library controls"><div class="library-search">${icon('search')}<input id="library-search" type="search" inputmode="search" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Search library" aria-label="Search mod library"><button type="button" class="search-clear" hidden>Clear</button></div><div class="library-filters" role="group" aria-label="Filter categories"><button type="button" data-filter="all" class="is-active">All <span>${total}</span></button><button type="button" data-filter="modpack">Mod Pack <span>${counts.modpack}</span></button><button type="button" data-filter="dlc">DLC <span>${counts.dlc}</span></button><button type="button" data-filter="graphics">Graphics <span>${counts.graphics}</span></button><button type="button" data-filter="language">Language <span>${counts.language}</span></button></div></section><section class="library-content" aria-labelledby="library-heading"><header class="library-heading"><div class="heading-copy"><span class="heading-icon">${icon('layers')}</span><div><small>LIBRARY</small><h2 id="library-heading">Featured Mods</h2></div></div><div class="heading-tools"><span class="result-count">${total} downloads</span><div class="view-toggle"><button type="button" data-view="grid" aria-label="Grid view">${gridIcon}</button><button type="button" data-view="list" aria-label="List view">${listIcon}</button></div></div></header><div class="library-feed">${ITEMS.map(card).join('')}</div><div class="library-empty" hidden>${icon('search')}<h3>No results</h3><p>Try another search or category.</p></div></section>`;
 const feed=main.querySelector('.library-feed'),cards=[...main.querySelectorAll('.library-card')],filters=[...main.querySelectorAll('.library-filters button')],search=main.querySelector('#library-search'),clear=main.querySelector('.search-clear'),count=main.querySelector('.result-count'),empty=main.querySelector('.library-empty'),heading=main.querySelector('#library-heading'),views=[...main.querySelectorAll('.view-toggle button')];let active='all',stored='grid';
 try{stored=localStorage.getItem('gtav-mod-library-view')||'grid'}catch{}if(!['grid','list'].includes(stored))stored='grid';const setView=view=>{feed.dataset.view=view;views.forEach(b=>{const on=b.dataset.view===view;b.classList.toggle('is-active',on);b.setAttribute('aria-pressed',String(on));});try{localStorage.setItem('gtav-mod-library-view',view)}catch{}};setView(stored);views.forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
 const setOpen=(card,open)=>{const panel=card.querySelector('.collection-panel'),btn=card.querySelector('.collection-toggle');if(!panel||!btn)return;card.classList.toggle('is-open',open);panel.hidden=!open;btn.setAttribute('aria-expanded',String(open));};main.querySelectorAll('.collection-toggle').forEach(btn=>btn.addEventListener('click',()=>{const c=btn.closest('.library-card');setOpen(c,!c.classList.contains('is-open'));}));
 const apply=()=>{const q=search.value.trim().toLowerCase();clear.hidden=!q;let downloads=0,visibleCards=0;cards.forEach(c=>{const show=(active==='all'||c.dataset.type===active)&&(!q||c.dataset.search.includes(q));c.hidden=!show;if(show){visibleCards++;downloads+=Number(c.dataset.count||1);if(q&&c.classList.contains('has-children'))setOpen(c,true);}});count.textContent=`${downloads} download${downloads===1?'':'s'}`;empty.hidden=visibleCards!==0;feed.hidden=visibleCards===0;const label=filters.find(b=>b.dataset.filter===active)?.childNodes[0]?.textContent?.trim();heading.textContent=active==='all'?'Featured Mods':label||'Featured Mods';};filters.forEach(btn=>btn.addEventListener('click',()=>{active=btn.dataset.filter;filters.forEach(b=>b.classList.toggle('is-active',b===btn));apply();}));search.addEventListener('input',apply);search.addEventListener('keydown',e=>{if(e.key==='Escape'&&search.value){search.value='';apply();search.blur();}});clear.addEventListener('click',()=>{search.value='';apply();search.focus({preventScroll:true});});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(mount,80),{once:true});else setTimeout(mount,80);
})();
